 static Page page(String id){for(Page p:PAGES)if(p.id.equals(id))return p;return null;}
 static String first(String category){for(Page p:PAGES)if(p.category.equals(category))return p.id;return "home";}
 static List<Page> category(String id){List<Page> rows=new ArrayList<>();for(Page p:PAGES)if(p.category.equals(id))rows.add(p);return rows;}
 static List<Page> search(String query){String q=query.trim().toLowerCase(Locale.ROOT);List<Page> rows=new ArrayList<>();if(q.isEmpty())return rows;for(Page p:PAGES)if((p.title+" "+p.detail+" "+p.category).toLowerCase(Locale.ROOT).contains(q))rows.add(p);return rows;}
 static String title(String category){for(String[] row:CATEGORIES)if(row[0].equals(category))return row[1];return "Settings";}
